sys_variable_value.value:
(function execute(inputs, outputs) {
function isDirector(title) {
        // Director+ titles
        var dirTitles = ["directeur", "directrice", "director", "vice-president", "vice president", "vice-président", "président", "president", "vp"];

        for(var i = 0; i < dirTitles.length; i++) {
            if(title.toLowerCase().indexOf(dirTitles[i]) > -1) return true;
        }

        return false;
    }
    
    function getDirector(user) {
        if(isDirector(user.title)) return user;

        return getDirector(user.manager)
    }

    var user = inputs.user;
    if(isDirector(user.title)) return;

    outputs.approval_user = getDirector(user);})(inputs, outputs);

